// Analisar contexto e determinar etapa da captação
const contexto = JSON.parse($json.contexto);
const mensagem = contexto.mensagem_original.toLowerCase();
const cliente = contexto.dados_entrada.cliente;
const canal = contexto.canal;

// Detectar se é proprietário existente
let proprietario_existente = false;
let dados_proprietario = {};

if (cliente) {
  // Verificar se já tem dados de proprietário
  proprietario_existente = cliente.tipo_interesse === 'venda';
  dados_proprietario = {
    nome: cliente.nome,
    telefone: cliente.telefone,
    email: cliente.email,
    cpf: cliente.cpf
  };
}

// Determinar etapa da captação
let etapa_captacao = 'saudacao_proprietario';

// Analisar dados já coletados para determinar próxima etapa
if (proprietario_existente) {
  if (!dados_proprietario.nome || dados_proprietario.nome.split(' ').length < 2) {
    etapa_captacao = 'dados_pessoais';
  } else {
    etapa_captacao = 'dados_imovel';
  }
}

// Detectar informações na mensagem
const informacoes_detectadas = {
  tipo_imovel: null,
  endereco: null,
  valor_pretendido: null,
  motivo_venda: null,
  urgencia: 'normal'
};

// Detectar tipo de imóvel
if (mensagem.includes('casa')) informacoes_detectadas.tipo_imovel = 'casa';
else if (mensagem.includes('apartamento') || mensagem.includes('apto')) informacoes_detectadas.tipo_imovel = 'apartamento';
else if (mensagem.includes('terreno')) informacoes_detectadas.tipo_imovel = 'terreno';
else if (mensagem.includes('comercial') || mensagem.includes('loja') || mensagem.includes('sala')) informacoes_detectadas.tipo_imovel = 'comercial';

// Detectar urgência
if (mensagem.includes('urgente') || mensagem.includes('rápido') || mensagem.includes('logo')) {
  informacoes_detectadas.urgencia = 'alta';
}

// Detectar motivo da venda
if (mensagem.includes('mudança') || mensagem.includes('mudar')) {
  informacoes_detectadas.motivo_venda = 'mudança';
} else if (mensagem.includes('financeiro') || mensagem.includes('dinheiro') || mensagem.includes('dívida')) {
  informacoes_detectadas.motivo_venda = 'financeiro';
} else if (mensagem.includes('upgrade') || mensagem.includes('maior') || mensagem.includes('melhor')) {
  informacoes_detectadas.motivo_venda = 'upgrade';
}

// Detectar valores
const valores = mensagem.match(/\d{1,3}(?:\.\d{3})*(?:,\d{2})?/g);
if (valores && valores.length > 0) {
  const valoresNumericos = valores.map(v => parseFloat(v.replace(/\./g, '').replace(',', '.')));
  informacoes_detectadas.valor_pretendido = Math.max(...valoresNumericos);
}

// Detectar endereço/localização
const bairros_comuns = [
  'centro', 'vila madalena', 'pinheiros', 'itaim', 'moema', 'vila olímpia',
  'brooklin', 'morumbi', 'jardins', 'perdizes', 'higienópolis', 'liberdade'
];

for (const bairro of bairros_comuns) {
  if (mensagem.includes(bairro)) {
    informacoes_detectadas.endereco = bairro;
    break;
  }
}

return {
  json: {
    contexto_original: contexto,
    etapa_captacao: etapa_captacao,
    proprietario_existente: proprietario_existente,
    dados_proprietario: dados_proprietario,
    informacoes_detectadas: informacoes_detectadas,
    canal: canal
  }
};

// Gerar resposta personalizada para captação
const dados = $json;
const etapa = dados.etapa_captacao;
const informacoes = dados.informacoes_detectadas;
const dadosProprietario = dados.dados_proprietario;
const canal = dados.canal;

// Templates de resposta por etapa
const templates = {
  saudacao_proprietario: {
    whatsapp: `Olá! 👋 Que bom que você quer anunciar seu imóvel conosco!

Somos especialistas em vendas e temos uma equipe dedicada para conseguir o melhor preço para você! 💰

Para começar, me conta:
🏠 Que tipo de imóvel você quer vender?

• Casa
• Apartamento
• Terreno
• Comercial (loja/sala)

É só me falar qual é! 😊`,
    email: `Olá!

Obrigado por escolher nossa imobiliária para vender seu imóvel.

Somos especialistas em vendas e temos uma equipe dedicada para conseguir o melhor resultado para você.

Para iniciar o processo, preciso saber que tipo de imóvel você deseja vender:

- Casa
- Apartamento
- Terreno
- Comercial

Por favor, me informe qual é o tipo do seu imóvel.`
  },

  dados_pessoais: {
    whatsapp: `Perfeito! ${informacoes.tipo_imovel ? informacoes.tipo_imovel.toUpperCase() + ' é uma excelente opção!' : 'Vamos começar!'} 🎉

Para fazer seu cadastro e iniciar a avaliação, preciso de alguns dados:

📝 *Seus dados:*
• Nome completo
• CPF
• Telefone (já tenho este! ✅)
• E-mail

Pode me passar essas informações? É rapidinho! ⚡`,
    email: `Excelente!

Para prosseguir com o cadastro do seu imóvel, preciso dos seguintes dados pessoais:

- Nome completo
- CPF
- Telefone
- E-mail

Por favor, me envie essas informações para darmos continuidade ao processo.`
  },

  dados_imovel: {
    whatsapp: `Ótimo, ${dadosProprietario.nome?.split(' ')[0]}! 👍

Agora vamos aos dados do seu ${informacoes.tipo_imovel || 'imóvel'}:

🏠 *Informações do imóvel:*
• Endereço completo
• Quantos quartos?
• Quantos banheiros?
• Área (m²)
• Valor que você gostaria de receber
• Tem garagem?

Pode ir me passando essas informações? 📋`,
    email: `Perfeito!

Agora preciso das informações do imóvel:

- Endereço completo
- Número de quartos
- Número de banheiros
- Área em metros quadrados
- Valor pretendido
- Vagas de garagem
- Estado de conservação

Por favor, me envie essas informações.`
  },

  documentacao: {
    whatsapp: `Excelente! Já tenho todas as informações básicas! ✅

📋 *Resumo do seu imóvel:*
• Tipo: ${informacoes.tipo_imovel || 'A definir'}
• Endereço: ${informacoes.endereco || 'A definir'}
• Valor pretendido: ${informacoes.valor_pretendido ? 'R$ ' + informacoes.valor_pretendido.toLocaleString('pt-BR') : 'A definir'}

Para finalizar o cadastro, vou precisar de:

📄 *Documentos:*
• Escritura ou matrícula
• IPTU atualizado
• Condomínio (se for apto)
• RG e CPF do proprietário

📸 *Fotos do imóvel*

Você tem esses documentos em mãos? Posso agendar uma visita para buscar! 🚗`,
    email: `Ótimo!

Para finalizar o cadastro, preciso dos seguintes documentos:

- Escritura ou matrícula do imóvel
- IPTU atualizado
- Taxa de condomínio (se aplicável)
- RG e CPF do proprietário
- Fotos do imóvel

Você pode enviar digitalizados ou podemos agendar uma visita para recolher os documentos.`
  },

  agendamento_avaliacao: {
    whatsapp: `Perfeito! 🎉

Seu imóvel está quase cadastrado! Agora vou agendar uma visita para:

✅ Fazer a avaliação profissional
✅ Tirar fotos profissionais
✅ Recolher os documentos
✅ Assinar o contrato de exclusividade

Qual o melhor dia e horário para você?

📅 *Horários disponíveis:*
• Manhã (9h às 12h)
• Tarde (14h às 17h)

Me fala quando é melhor para você! 😊`,
    email: `Excelente!

Vamos agendar uma visita técnica para:

- Avaliação profissional do imóvel
- Sessão de fotos profissionais
- Recolhimento de documentos
- Assinatura do contrato

Por favor, me informe sua disponibilidade de horário para agendarmos a visita.`
  }
};

// Selecionar template baseado na etapa e canal
let resposta = templates[etapa]?.[canal] || templates[etapa]?.whatsapp || 'Desculpe, houve um erro. Pode repetir sua mensagem?';

// Personalizar resposta com informações detectadas
if (informacoes.tipo_imovel && etapa === 'saudacao_proprietario') {
  resposta = resposta.replace('Que tipo de imóvel', `Vi que você mencionou ${informacoes.tipo_imovel}! Que tipo de imóvel`);
}

if (informacoes.urgencia === 'alta') {
  if (canal === 'whatsapp') {
    resposta += `\n\n⚡ *URGENTE:* Vi que você tem pressa! Vou priorizar seu atendimento e podemos agilizar todo o processo!`;
  } else {
    resposta += `\n\nObservei que você tem urgência. Vou priorizar seu atendimento para agilizar o processo.`;
  }
}

if (informacoes.valor_pretendido && etapa === 'dados_imovel') {
  resposta += `\n\nVi que você mencionou R$ ${informacoes.valor_pretendido.toLocaleString('pt-BR')}. Vamos trabalhar para conseguir o melhor valor para você!`;
}

// Determinar próxima ação
let proxima_acao = 'aguardar_resposta';
let transferir_para = null;

if (etapa === 'agendamento_avaliacao') {
  proxima_acao = 'agendar_visita_tecnica';
}

return {
  json: {
    resposta: resposta,
    etapa_atual: etapa,
    proxima_acao: proxima_acao,
    transferir_para: transferir_para,
    dados_para_salvar: {
      ...dadosProprietario,
      ...informacoes
    },
    contexto_completo: dados
  }
};
